SELECT FROM doctor doc INNER JOIN department dept ON dept.id = doc.department_id WHERE doc.status = 1 AND dept.status = 1 AND doc.department_id = #{departmentId}
AND (doc.name LIKE CONCAT('%', #{keyword}, '%') OR dept.name LIKE CONCAT('%', #{keyword}, '%') OR doc.introduction LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY doc.sort_order ASC, doc.id ASC
